class Solution:
    def minimumOperations(self, nums: list[int]) -> int:
        return sum(1 for x in nums if x % 3 != 0)

class Solution {
public:
    int minimumOperations(vector<int>& nums) {
        int ans = 0;
        for (int x : nums) {
            if (x % 3 != 0) ans++;
        }
        return ans;
    }
};

class Solution {
    public int minimumOperations(int[] nums) {
        int ans = 0;
        for (int x : nums) {
            if (x % 3 != 0) ans++;
        }
        return ans;
    }
}

var minimumOperations = function(nums) {
    let ans = 0;
    for (const x of nums) {
        if (x % 3 !== 0) ans++;
    }
    return ans;
};
